  const submit = trpc.platform.finance.pettyCash.request.useMutation({ onSuccess: () => { utils.platform.finance.pettyCash.list.invalidate(); setForm({ requestDate: today, department: "general", category: "expense", amount: "", payee: "", purpose: "", sourceReference: "" }); toast.success("Controlled expense request submitted"); }, onError: (error) => toast.error(error.message) });
  return <Card className="mt-6"><Title title="Controlled allocation request" hint="Use this detailed form when the department, request type, and receipt or voucher reference must be retained for accounting."/><div className="grid gap-3 md:grid-cols-3"><Field label="Request date"><Input type="date" value={form.requestDate} onChange={(event) => setForm({ ...form, requestDate: event.target.value })}/></Field><Field label="Department"><Select value={form.department} onChange={(event) => setForm({ ...form, department: event.target.value })}>{["front_office", "housekeeping", "maintenance", "aqua_park", "fnb", "management", "general"].map((entry) => <option key={entry} value={entry}>{entry.replace("_", " ")}</option>)}</Select></Field><Field label="Request type"><Select value={form.category} onChange={(event) => setForm({ ...form, category: event.target.value })}><option value="expense">Expense</option><option value="petty_cash">Petty cash</option><option value="reimbursement">Reimbursement</option></Select></Field><Field label="Amount (OMR)"><Input inputMode="decimal" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })}/></Field><Field label="Payee"><Input value={form.payee} onChange={(event) => setForm({ ...form, payee: event.target.value })}/></Field><Field label="Receipt / voucher reference"><Input placeholder="e.g. PC-2026-014" value={form.sourceReference} onChange={(event) => setForm({ ...form, sourceReference: event.target.value })}/></Field></div><Field label="Business purpose"><Textarea value={form.purpose} onChange={(event) => setForm({ ...form, purpose: event.target.value })}/></Field><div className="mt-4"><Save pending={submit.isPending} onClick={() => form.amount && form.payee && form.purpose ? submit.mutate(form as any) : toast.error("Add amount, payee and business purpose")}>Submit controlled request</Save></div></Card>;
