function OperationalFinanceExtension() {
  const { user } = useAuth(); const utils = trpc.useUtils();
  const canManage = user?.role === "manager" || user?.role === "admin"; const isAdmin = user?.role === "admin";
  const [range, setRange] = useState({ from: `${today.slice(0, 8)}01`, to: today });
  const [categoryForm, setCategoryForm] = useState({ id: "", name: "", code: "" });
  const [expenseForm, setExpenseForm] = useState({ id: "", businessDate: today, categoryId: "", amount: "", payee: "", description: "", department: "general" as any });
  const { data: categories = [] } = trpc.platform.finance.expenseCategories.list.useQuery({ includeInactive: isAdmin }, { enabled: canManage });
  const { data: expenses = [] } = trpc.platform.finance.expenses.list.useQuery(range, { enabled: canManage });
  const { data: summary } = trpc.platform.finance.operationalSummary.useQuery(range, { enabled: canManage });
  const invalidate = () => { utils.platform.finance.expenseCategories.invalidate(); utils.platform.finance.expenses.invalidate(); utils.platform.finance.operationalSummary.invalidate(); utils.platform.finance.invalidate(); };
  const saveCategory = trpc.platform.finance.expenseCategories.create.useMutation({ onSuccess: () => { invalidate(); setCategoryForm({ id: "", name: "", code: "" }); toast.success("Expense category added"); }, onError: (error) => toast.error(error.message) });
  const updateCategory = trpc.platform.finance.expenseCategories.update.useMutation({ onSuccess: () => { invalidate(); setCategoryForm({ id: "", name: "", code: "" }); toast.success("Expense category updated"); }, onError: (error) => toast.error(error.message) });
  const removeCategory = trpc.platform.finance.expenseCategories.delete.useMutation({ onSuccess: () => { invalidate(); toast.success("Expense category deleted"); }, onError: (error) => toast.error(error.message) });
  const saveExpense = trpc.platform.finance.expenses.create.useMutation({ onSuccess: () => { invalidate(); setExpenseForm({ id: "", businessDate: today, categoryId: "", amount: "", payee: "", description: "", department: "general" }); toast.success("Expense recorded"); }, onError: (error) => toast.error(error.message) });
  const updateExpense = trpc.platform.finance.expenses.update.useMutation({ onSuccess: () => { invalidate(); setExpenseForm({ id: "", businessDate: today, categoryId: "", amount: "", payee: "", description: "", department: "general" }); toast.success("Expense updated"); }, onError: (error) => toast.error(error.message) });
  const removeExpense = trpc.platform.finance.expenses.delete.useMutation({ onSuccess: () => { invalidate(); toast.success("Expense deleted"); }, onError: (error) => toast.error(error.message) });
  if (!canManage) return <Card className="mt-6"><Title title="Operating expense controls"/><p className="text-sm text-[#657168]">Only managers and administrators can access categorized expense records and operating financial reports.</p></Card>;
  const activeCategories = categories.filter((category: any) => category.isActive);
  const editingExpense = Boolean(expenseForm.id); const editingCategory = Boolean(categoryForm.id);
  return <section className="mt-6 space-y-6"><Header eyebrow="Operating finance" title="Revenue versus expenses" description="Record dated, categorized costs and compare them against persistent transaction-ticket revenue for the selected period."/>
    <div className="grid gap-4 sm:grid-cols-3"><Card className="relative overflow-hidden !border-[#123750] !bg-[#0a2035] !text-white"><div className="absolute -right-8 -top-10 h-28 w-28 rounded-full bg-[#22c5b1]/25 blur-2xl"/><div className="relative text-[10px] font-bold uppercase tracking-[.16em] text-[#91e9dd]">Ticket revenue</div><div className="relative mt-3 font-serif text-3xl tracking-[-.03em]">{money(summary?.revenue)}</div><div className="relative mt-2 text-xs text-[#aec5cf]">From sequential sales tickets</div></Card><Card className="border-[#f2dfbd] bg-[#fffdf8]"><div className="text-[10px] font-bold uppercase tracking-[.16em] text-[#a26b18]">Categorized expenses</div><div className="mt-3 font-serif text-3xl tracking-[-.03em] text-[#bd5149]">{money(summary?.expenses)}</div><div className="mt-2 text-xs text-[#8a7a62]">From the expense ledger</div></Card><Card className="border-[#c9eae4] bg-[#f4fffc]"><div className="text-[10px] font-bold uppercase tracking-[.16em] text-[#087d76]">Net operating result</div><div className={styles("mt-3 font-serif text-3xl tracking-[-.03em]", Number(summary?.net || 0) >= 0 ? "text-[#087d76]" : "text-[#bd5149]")}>{money(summary?.net)}</div><div className="mt-2 text-xs text-[#5d7c7c]">Revenue less expenses</div></Card></div>
    <Card><Title title="Report period" hint="Totals use only the new persistent sales tickets and expense records, so this comparison does not double count legacy finance entries."/><div className="grid gap-3 sm:grid-cols-3"><Field label="From"><Input type="date" value={range.from} onChange={(event) => setRange({ ...range, from: event.target.value })}/></Field><Field label="To"><Input type="date" value={range.to} onChange={(event) => setRange({ ...range, to: event.target.value })}/></Field><div className="flex items-end"><Button variant="outline" onClick={() => { setRange({ from: `${today.slice(0, 8)}01`, to: today }); toast.success("Report period reset to this month"); }}>This month</Button></div></div></Card>
    <div className={styles("grid gap-6", isAdmin ? "xl:grid-cols-2" : "xl:grid-cols-1")}>
      {isAdmin && <Card><Title title="Expense category administration" hint="Administrators can add, rename, deactivate, or delete categories. Historical expense records retain their category name."/><div className="grid gap-3 sm:grid-cols-[1fr_.6fr_auto]"><Field label="Category name"><Input value={categoryForm.name} onChange={(event) => setCategoryForm({ ...categoryForm, name: event.target.value })}/></Field><Field label="Code"><Input value={categoryForm.code} onChange={(event) => setCategoryForm({ ...categoryForm, code: event.target.value.toUpperCase() })}/></Field><div className="flex items-end"><Save pending={saveCategory.isPending || updateCategory.isPending} onClick={() => { if (!categoryForm.name.trim() || !categoryForm.code.trim()) return toast.error("Add a category name and code"); if (editingCategory) updateCategory.mutate({ id: Number(categoryForm.id), name: categoryForm.name.trim(), code: categoryForm.code.trim() }); else saveCategory.mutate({ name: categoryForm.name.trim(), code: categoryForm.code.trim() }); }}>{editingCategory ? "Update" : "Add category"}</Save></div></div>{editingCategory && <Button className="mt-3" variant="outline" onClick={() => setCategoryForm({ id: "", name: "", code: "" })}>Cancel editing</Button>}<div className="mt-5 divide-y divide-[#eee8dd]">{categories.length ? categories.map((category: any) => <div className="flex flex-wrap items-center justify-between gap-3 py-3" key={category.id}><div><b>{category.name}</b><span className="ml-2 font-mono text-xs text-[#9c7545]">{category.code}</span>{!category.isActive && <span className="ml-2 text-xs text-[#a74743]">Inactive</span>}</div><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => setCategoryForm({ id: String(category.id), name: category.name, code: category.code })}>Edit</Button><Button size="sm" variant="outline" onClick={() => updateCategory.mutate({ id: category.id, isActive: !category.isActive })}>{category.isActive ? "Deactivate" : "Activate"}</Button><Button size="sm" variant="outline" onClick={() => { if (window.confirm(`Delete ${category.name}? Existing expenses keep their historical category label.`)) removeCategory.mutate({ id: category.id }); }}>Delete</Button></div></div>) : <Empty text="Add the first expense category to begin recording categorized costs."/>}</div></Card>}
      <Card><Title title={editingExpense ? "Edit dated expense" : "Record dated expense"} hint="Managers and administrators can maintain the expense ledger. The selected category is captured with the transaction."/><div className="grid gap-3 sm:grid-cols-2"><Field label="Expense date"><Input type="date" value={expenseForm.businessDate} onChange={(event) => setExpenseForm({ ...expenseForm, businessDate: event.target.value })}/></Field><Field label="Category"><Select value={expenseForm.categoryId} onChange={(event) => setExpenseForm({ ...expenseForm, categoryId: event.target.value })}><option value="">Select category</option>{activeCategories.map((category: any) => <option key={category.id} value={category.id}>{category.name}</option>)}</Select></Field><Field label="Amount (OMR)"><Input inputMode="decimal" value={expenseForm.amount} onChange={(event) => setExpenseForm({ ...expenseForm, amount: event.target.value })}/></Field><Field label="Payee (optional)"><Input value={expenseForm.payee} onChange={(event) => setExpenseForm({ ...expenseForm, payee: event.target.value })}/></Field><Field label="Department"><Select value={expenseForm.department} onChange={(event) => setExpenseForm({ ...expenseForm, department: event.target.value })}>{["front_office", "housekeeping", "maintenance", "aqua_park", "fnb", "management", "general"].map((entry) => <option key={entry} value={entry}>{entry.replace("_", " ")}</option>)}</Select></Field><Field label="Description"><Input value={expenseForm.description} onChange={(event) => setExpenseForm({ ...expenseForm, description: event.target.value })}/></Field></div><div className="mt-4 flex flex-wrap gap-3"><Save pending={saveExpense.isPending || updateExpense.isPending} onClick={() => { if (!expenseForm.categoryId || !expenseForm.amount || !expenseForm.description.trim()) return toast.error("Choose a category and add amount and description"); const payload = { businessDate: expenseForm.businessDate, categoryId: Number(expenseForm.categoryId), amount: expenseForm.amount, payee: expenseForm.payee || undefined, description: expenseForm.description.trim(), department: expenseForm.department }; if (editingExpense) updateExpense.mutate({ id: Number(expenseForm.id), ...payload }); else saveExpense.mutate(payload); }}>{editingExpense ? "Save expense changes" : "Record expense"}</Save>{editingExpense && <Button variant="outline" onClick={() => setExpenseForm({ id: "", businessDate: today, categoryId: "", amount: "", payee: "", description: "", department: "general" })}>Cancel editing</Button>}</div></Card>
    </div>
    <Card><Title title="Expense ledger" hint="Edit or remove an expense record when the underlying business record needs correction."/>{expenses.length ? <div className="divide-y divide-[#eee8dd]">{expenses.map((expense: any) => <div className="flex flex-wrap items-center justify-between gap-3 py-3" key={expense.id}><div><div className="font-medium">{expense.categoryName} · {expense.description}</div><div className="text-xs text-[#7a867f]">{fmt(expense.businessDate)} · {expense.department.replace("_", " ")} · {expense.payee || "No payee"}</div></div><div className="flex items-center gap-3"><b className="font-serif text-lg text-[#a74743]">{money(expense.amount)}</b><Button size="sm" variant="outline" onClick={() => setExpenseForm({ id: String(expense.id), businessDate: String(expense.businessDate).slice(0, 10), categoryId: String(expense.categoryId || ""), amount: String(expense.amount), payee: expense.payee || "", description: expense.description, department: expense.department })}>Edit</Button><Button size="sm" variant="outline" onClick={() => { if (window.confirm("Delete this expense record?")) removeExpense.mutate({ id: expense.id }); }}>Delete</Button></div></div>)}</div> : <Empty text="Select a date range or record the first categorized expense."/>}</Card>
  </section>;
}

export default function ERPOperationsPage() {
  const { user } = useAuth(); const [location, setLocation] = useLocation();
  useEffect(() => { if (user && !permittedPath(location, user.role)) setLocation("/tickets"); }, [location, setLocation, user]);
  if (user && !permittedPath(location, user.role)) return null;
  if (location === "/tickets") return <TransactionTicketDesk/>;
  if (location === "/finance") return <OperationalFinanceExtension/>;
  return <TransactionTicketDesk/>;
}
